char * * process_alsos ( struct starter_config * cfg , struct starter_conn * conn , struct config_parsed * cfgp , char * * alsos , int alsosize , bool alsoflip , err_t * perr ) { int alsoplace ; unsigned int err ; alsoplace = 0 ; while ( alsoplace < alsosize && alsos [ alsoplace ] != NULL && alsoplace < ALSO_LIMIT ) { struct section_list * sl1 ; for ( sl1 = cfgp -> sections . tqh_first ; sl1 != NULL && strcasecmp ( alsos [ alsoplace ] , sl1 -> name ) != 0 ; sl1 = sl1 -> link . tqe_next ) { } starter_log ( LOG_LEVEL_DEBUG , "\twhile loading conn '%s' also including '%s'" , conn -> name , alsos [ alsoplace ] ) ; if ( sl1 && ! sl1 -> beenhere ) { conn -> strings_set [ KSF_ALSO ] = FALSE ; pfreeany ( conn -> strings [ KSF_ALSO ] ) ; conn -> strings [ KSF_ALSO ] = NULL ; sl1 -> beenhere = TRUE ; err += translate_conn ( conn , sl1 , k_set , perr , alsoflip ) ; if ( conn -> strings [ KSF_ALSO ] ) { char * * newalsos ; int newalsoplace ; newalsos = new_list ( conn -> strings [ KSF_ALSO ] ) ; if ( newalsos && newalsos [ 0 ] != NULL ) { char * * ra ; for ( newalsoplace = 0 ; newalsos [ newalsoplace ] != NULL ; newalsoplace ++ ) { } ra = alloc_bytes ( ( alsosize + newalsoplace + 1 ) * sizeof ( char * ) , "conn->alsos" ) ; memcpy ( ra , alsos , alsosize * sizeof ( char * ) ) ; alsos = ra ; for ( newalsoplace = 0 ; newalsos [ newalsoplace ] != NULL ; newalsoplace ++ ) { assert ( conn != NULL ) ; assert ( conn -> name != NULL ) ; starter_log ( LOG_LEVEL_DEBUG , "\twhile processing section '%s' added also=%s" , sl1 -> name , newalsos [ newalsoplace ] ) ; alsos [ alsosize ++ ] = clone_str ( newalsos [ newalsoplace ] , "alsos" ) ; } alsos [ alsosize ] = NULL ; } FREE_LIST ( newalsos ) ; } } alsoplace ++ ; if ( alsoplace >= ALSO_LIMIT ) { starter_log ( LOG_LEVEL_INFO , "while loading conn '%s', too many also= used at section %s. Limit is %d" , conn -> name , conn -> alsos [ alsoplace ] , ALSO_LIMIT ) ; * perr = "too many also" ; return NULL ; } } return alsos ; } 